import React, { useState, useEffect, useCallback } from 'react';
import { Auth } from 'aws-amplify';
import { useNavigate } from 'react-router-dom';
import {
    Box,
    Button,
    TextField,
    Typography,
    Container,
    Paper,
    Alert
} from '@mui/material';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    const checkAuth = useCallback(async () => {
        try {
            const user = await Auth.currentAuthenticatedUser();
            if (user) {
                navigate('/users');
            }
        } catch (err) {
            console.log('No hay sesión activa');
        }
    }, [navigate]);

    useEffect(() => {
        checkAuth();
    }, [checkAuth]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            // Intentar iniciar sesión
            const user = await Auth.signIn(username, password);
            console.log('Login exitoso:', user);

            // Si signInUserSession es null, intentar obtener una nueva sesión
            if (!user.signInUserSession) {
                console.log('Intentando obtener nueva sesión...');
                const newSession = await Auth.currentSession();
                if (!newSession) {
                    throw new Error('No se pudo obtener la sesión');
                }
                console.log('Nueva sesión obtenida:', newSession);
            }

            // Verificar la autenticación
            const currentUser = await Auth.currentAuthenticatedUser();
            console.log('Usuario actual:', currentUser);

            if (currentUser) {
                // Obtener la sesión
                const session = await Auth.currentSession();
                console.log('Sesión actual:', session);

                // Verificar que el token sea válido
                const token = session.getIdToken().getJwtToken();
                if (token) {
                    console.log('Token obtenido correctamente');
                    // Guardar el token en localStorage
                    localStorage.setItem('token', token);
                    navigate('/users');
                } else {
                    throw new Error('Token no válido');
                }
            } else {
                throw new Error('No se pudo obtener el usuario actual');
            }
        } catch (err) {
            console.error('Error en login:', err);
            if (err.code === 'UserNotConfirmedException') {
                setError('Usuario no confirmado. Por favor, verifica tu email.');
            } else if (err.code === 'NotAuthorizedException') {
                setError('Credenciales incorrectas');
            } else if (err.code === 'UserNotFoundException') {
                setError('Usuario no encontrado');
            } else if (err.code === 'InvalidParameterException') {
                setError('Parámetros de autenticación inválidos');
            } else {
                setError(err.message || 'Error al iniciar sesión');
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <Container component="main" maxWidth="xs">
            <Box
                sx={{
                    marginTop: 8,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                }}
            >
                <Paper elevation={3} sx={{ p: 4, width: '100%' }}>
                    <Typography component="h1" variant="h5" align="center" gutterBottom>
                        Iniciar Sesión
                    </Typography>
                    {error && (
                        <Alert severity="error" sx={{ mb: 2 }}>
                            {error}
                        </Alert>
                    )}
                    <Box component="form" onSubmit={handleSubmit} sx={{ mt: 1 }}>
                        <TextField
                            margin="normal"
                            required
                            fullWidth
                            id="username"
                            label="Usuario"
                            name="username"
                            autoComplete="username"
                            autoFocus
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            disabled={loading}
                        />
                        <TextField
                            margin="normal"
                            required
                            fullWidth
                            name="password"
                            label="Contraseña"
                            type="password"
                            id="password"
                            autoComplete="current-password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            disabled={loading}
                        />
                        <Button
                            type="submit"
                            fullWidth
                            variant="contained"
                            sx={{ mt: 3, mb: 2 }}
                            disabled={loading}
                        >
                            {loading ? 'Iniciando sesión...' : 'Ingresar'}
                        </Button>
                    </Box>
                </Paper>
            </Box>
        </Container>
    );
};

export default Login;
